import React, { useState } from 'react';
import axios from 'axios';

function BookingPage() {
  const [slotId, setSlotId] = useState('');
  const [userId, setUserId] = useState('');
  const [bookingDate, setBookingDate] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [message, setMessage] = useState('');

  const handleBooking = async () => {
    try {
      const bookingData = {
        slotId: parseInt(slotId),
        userId: parseInt(userId),
        bookingDate,
        startTime,
        endTime,
      };

      const response = await axios.post('http://localhost:8080/bookings', bookingData);
      
      if (response.status === 200 || response.status === 201) {
        setMessage('✅ Booking successful');
      } else {
        setMessage('❌ Error creating booking.');
      }
    } catch (error) {
      console.error(error);
      setMessage('❌ Error creating booking.');
    }
  };

  return (
    <div>
      <h2>Book a Slot</h2>
      <input type="number" placeholder="Slot ID" value={slotId} onChange={(e) => setSlotId(e.target.value)} />
      <input type="number" placeholder="User ID" value={userId} onChange={(e) => setUserId(e.target.value)} />
      <input type="date" placeholder="Date" value={bookingDate} onChange={(e) => setBookingDate(e.target.value)} />
      <input type="time" placeholder="Start Time" value={startTime} onChange={(e) => setStartTime(e.target.value)} />
      <input type="time" placeholder="End Time" value={endTime} onChange={(e) => setEndTime(e.target.value)} />
      <button onClick={handleBooking}>Book Slot</button>
      <p>{message}</p>
    </div>
  );
}

export default BookingPage;
